export type JobStatus = "queued" | "in_flight" | "done" | "failed";

export interface Job {
  id: string;
  kind: string;
  payload: Record<string, unknown>;
  priority: number; // higher runs first
  status: JobStatus;
  attempts: number;
  createdAt: number; // epoch ms
  doneAt?: number; // epoch ms, set when status becomes "done"
}

