import type { Job } from "../shared/types";

// In-memory store. A real system would use a database; the bug surface here is entirely in the scheduling
// and lifecycle logic, not persistence.
const JOBS = new Map<string, Job>();
let nextId = 1;

export function enqueue(kind: string, payload: Record<string, unknown>, priority = 0): Job {
  const job: Job = {
    id: `j${nextId++}`,
    kind,
    payload,
    priority,
    status: "queued",
    attempts: 0,
    createdAt: Date.now(),
  };
  JOBS.set(job.id, job);
  return job;
}

// Returns the next queued job to run, or undefined if none are ready. Callers must call markInFlight (or
// enqueue never returns the same job to two concurrent callers) before doing any async work.
export function dequeue(): Job | undefined {
  const queued = [...JOBS.values()].filter((j) => j.status === "queued");
  if (queued.length === 0) return undefined;
  // BUG A: sorted by createdAt (insertion order) instead of priority -- a low-priority job enqueued first
  // always runs before a high-priority job enqueued later, defeating the whole point of the priority field.
  queued.sort((a, b) => a.createdAt - b.createdAt);
  return queued[0];
}

export function markInFlight(id: string): void {
  const job = JOBS.get(id);
  if (job) job.status = "in_flight";
}

export function markDone(id: string): void {
  const job = JOBS.get(id);
  if (job) {
    job.status = "done";
    job.doneAt = Date.now();
  }
}

export function markFailed(id: string): void {
  const job = JOBS.get(id);
  if (job) {
    job.status = "failed";
    job.attempts += 1;
  }
}

export function getJob(id: string): Job | undefined {
  return JOBS.get(id);
}

export function allJobs(): Job[] {
  return [...JOBS.values()];
}

// Retention: completed jobs older than this are pruned so the store doesn't grow forever.
const RETENTION_MS = 24 * 60 * 60 * 1000; // 24h

export function pruneCompleted(now = Date.now()): number {
  let pruned = 0;
  for (const [id, job] of JOBS) {
    // BUG D: checks createdAt instead of doneAt -- a job that sat in the queue for a long time before
    // finally running gets pruned immediately after completing, while a job that ran quickly but was
    // enqueued recently is kept even once its retention window (measured from completion) has long passed.
    if (job.status === "done" && job.createdAt !== undefined && now - job.createdAt > RETENTION_MS) {
      JOBS.delete(id);
      pruned++;
    }
  }
  return pruned;
}

export function resetForTest(): void {
  JOBS.clear();
  nextId = 1;
}

