import { dequeue, markInFlight, markDone, markFailed, getJob } from "./queue";
import { runHandler } from "./jobs/handlers";

const MAX_ATTEMPTS = 5;
const BASE_DELAY_MS = 200;
const MAX_DELAY_MS = 10_000;

// Exponential backoff with a cap: attempt 1 -> BASE, attempt 2 -> BASE*2, attempt 3 -> BASE*4, ... capped at
// MAX_DELAY_MS. `attempt` is 1-based (the first retry after the first failure is attempt 1).
export function computeBackoffMs(attempt: number): number {
  // BUG C: linear instead of exponential -- retries barely slow down as they pile up, so a persistently
  // failing job (e.g. a rate-limited external call) gets hammered at nearly a constant rate instead of
  // backing off, which is the entire reason a backoff function exists.
  const delay = BASE_DELAY_MS * attempt;
  return Math.min(delay, MAX_DELAY_MS);
}

// Runs one job to completion or failure. Idempotency contract: a job's side effect (whatever runHandler does)
// must happen at most once per job, even if processOnce is called again after the job already reached a
// terminal state (a retry driven by a stale queue view, a duplicate worker, etc. must be a safe no-op).
export async function processOnce(id: string): Promise<"done" | "failed" | "skipped" | "not_found"> {
  const job = getJob(id);
  if (!job) return "not_found";

  // BUG B: no check for an already-terminal job before running the handler again -- calling processOnce on a
  // job that is already "done" re-runs its side effect (e.g. sends a second receipt email, charges a card
  // twice) instead of being a safe no-op.
  markInFlight(id);
  try {
    await runHandler(job);
    markDone(id);
    return "done";
  } catch {
    markFailed(id);
    return "failed";
  }
}

export function shouldGiveUp(attempts: number): boolean {
  return attempts >= MAX_ATTEMPTS;
}

