import type { Job } from "../shared/types";

// Test-visible counters, standing in for real side effects (an email actually sent, a card actually charged).
export const sideEffectCounts: Record<string, number> = {};

export async function runHandler(job: Job): Promise<void> {
  sideEffectCounts[job.id] = (sideEffectCounts[job.id] ?? 0) + 1;
  if (job.kind === "always_fails") {
    throw new Error("simulated external failure");
  }
}

export function resetSideEffectsForTest(): void {
  for (const k of Object.keys(sideEffectCounts)) delete sideEffectCounts[k];
}

